const M:usize=128;const R:usize=9;const E:i32=-1;
const Node=struct{v:i64,child:i32,sibling:i32,degree:usize};
const Heap=struct{nodes:[M]Node,roots:[R]i32,used:usize,size:usize,
fn link(h:*Heap,a:i32,b:i32)i32{const p=if(h.nodes[@intCast(a)].v<h.nodes[@intCast(b)].v)a else b;const c=if(p==a)b else a;const pi:usize=@intCast(p);const ci:usize=@intCast(c);h.nodes[ci].sibling=h.nodes[pi].child;h.nodes[pi].child=c;h.nodes[pi].degree+=1;return p;}
fn add(h:*Heap,initial:i32)void{var root=initial;var d=h.nodes[@intCast(root)].degree;while(h.roots[d]!=E){root=h.link(root,h.roots[d]);h.roots[d]=E;d+=1;}h.roots[d]=root;}
fn insert(h:*Heap,v:i64)void{const r:i32=@intCast(h.used);h.used+=1;h.nodes[@intCast(r)]=.{.v=v,.child=E,.sibling=E,.degree=0};h.size+=1;h.add(r);}
fn minroot(h:*const Heap)i32{var best=E;for(h.roots)|r|{if(r!=E and (best==E or h.nodes[@intCast(r)].v<h.nodes[@intCast(best)].v))best=r;}return best;}
fn extract(h:*Heap)i64{const b:usize=@intCast(h.minroot());const d=h.nodes[b].degree;const v=h.nodes[b].v;h.roots[d]=E;var c=h.nodes[b].child;while(c!=E){const ci:usize=@intCast(c);const next=h.nodes[ci].sibling;h.nodes[ci].sibling=E;h.add(c);c=next;}h.size-=1;return v;}};
export fn binomial_heap(input:[*c]const i64,len:usize,out:[*c]u8,cap:usize)i64{if(input==null or len<1 or input[0]<0 or input[0]>@as(i64,@intCast(M)))return -1;const n:usize=@intCast(input[0]);if(len!=1+2*n)return -1;var q:usize=0;var size:usize=0;for(0..n)|i|{const op=input[1+2*i];const v=input[2+2*i];if(op==0){if(v< -2147483648 or v>2147483647)return -1;size+=1;}else if(op>=1 and op<=3){if(v!=0 or ((op==1 or op==2) and size==0))return -1;if(op==2)size-=1;q+=1;}else return -1;}const need=q*8;if(cap<need or (need>0 and out==null))return -2;var h=Heap{.nodes=undefined,.roots=[_]i32{E}**R,.used=0,.size=0};var w:usize=0;for(0..n)|i|{const op=input[1+2*i];const v=input[2+2*i];if(op==0){h.insert(v);continue;}const r:i64=if(op==1)h.nodes[@intCast(h.minroot())].v else if(op==2)h.extract() else @as(i64,@intFromBool(h.size==0));const bits:u64=@bitCast(r);for(0..8)|b|out[w*8+b]=@truncate(bits>>@as(u6,@intCast(8*b)));w+=1;}return @intCast(w);}
